import{_ as i,o as t,c as o,ag as a}from"./chunks/framework.DC2M1AAK.js";const p=JSON.parse('{"title":"Production-readiness checklist","description":"","frontmatter":{},"headers":[],"relativePath":"run/production-checklist.md","filePath":"run/production-checklist.md"}'),r={name:"run/production-checklist.md"};function s(n,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="production-readiness-checklist" tabindex="-1">Production-readiness checklist <a class="header-anchor" href="#production-readiness-checklist" aria-label="Permalink to &quot;Production-readiness checklist&quot;">​</a></h1><p>Every item here was a real blocker or incident in the first production vertical (an audit found eight blockers; the hardening that followed produced this list). Walk it before any deploy; walk §1–3 at design time.</p><h2 id="_1-identity-session-security" tabindex="-1">1. Identity &amp; session security <a class="header-anchor" href="#_1-identity-session-security" aria-label="Permalink to &quot;1. Identity &amp; session security&quot;">​</a></h2><ul><li>[ ] Login required (<code>AGENT_REQUIRE_LOGIN</code> unset = on). Dev convenience never becomes identity.</li><li>[ ] Identity VERIFIED against your auth service (<code>AGENT_AUTH_VERIFY_URL</code>), cached 60 s, failing closed (401 on rejection, 503 when unreachable). A bare JWT decode scopes listings in dev only.</li><li>[ ] A session id is never a credential: every session route checks the owner and answers 404 on a mismatch.</li><li>[ ] Admin routes (<code>/api/sessions</code>, <code>/api/metrics</code>, <code>/api/usage</code>, <code>/api/system-prompt</code>, <code>/api/decide</code>) require <code>AGENT_ADMIN_KEY</code> and are DISABLED when none is set in a keyed/login deployment.</li><li>[ ] The user&#39;s token rides MCP <code>_meta</code>, never model-visible arguments; never persisted; re-supplied per turn. An agent-token exchange keeps the broad upstream token out of web views (docs/SDK-AUTH.md).</li><li>[ ] Tokens, keys, passwords, OTPs and private notes never appear in logs (<code>redact()</code>), spans or ledgers.</li></ul><h2 id="_2-write-path-integrity" tabindex="-1">2. Write-path integrity <a class="header-anchor" href="#_2-write-path-integrity" aria-label="Permalink to &quot;2. Write-path integrity&quot;">​</a></h2><ul><li>[ ] The confirm gate ×3: skill rule, tool schema (<code>confirmed:true</code> + <code>AGENT_ALLOW_WRITES === &quot;true&quot;</code>), runtime guard (summary shown for this draft + whole-content yes).</li><li>[ ] The backend was PROBED: real mandatories, schema warts, which base URLs share a database, whether a GET writes. Findings live in the schema registry.</li><li>[ ] Timeout + idempotency on the write (key = session + draft fingerprint; reconcile before retrying).</li><li>[ ] No silent fuzzy fallback on the write path; the write uses only ids the user confirmed.</li><li>[ ] Links are tool-composed or templated (<code>AGENT_ENTITY_DEEPLINK</code>), never model-invented; the scheme allowlist is on (<code>AGENT_LINK_SCHEMES</code> for your app&#39;s scheme).</li><li>[ ] Attested lists configured for anything published under the user&#39;s name (<code>attested_lists</code>).</li></ul><h2 id="_3-client-security" tabindex="-1">3. Client security <a class="header-anchor" href="#_3-client-security" aria-label="Permalink to &quot;3. Client security&quot;">​</a></h2><ul><li>[ ] CORS allowlist (<code>AGENT_CORS_ORIGINS</code>), gateway keys (<code>AGENT_GATEWAY_KEYS</code>), message cap (<code>AGENT_MAX_MESSAGE_CHARS</code>), security headers (always on).</li><li>[ ] History replay carries user/assistant prose + blocks only; tool payloads never leave the server.</li><li>[ ] The injection preamble is in every prompt; an injection scenario is in every suite.</li><li>[ ] The widget script URL is pinned to its version behind any caching proxy.</li></ul><h2 id="_4-lifecycle-resilience" tabindex="-1">4. Lifecycle &amp; resilience <a class="header-anchor" href="#_4-lifecycle-resilience" aria-label="Permalink to &quot;4. Lifecycle &amp; resilience&quot;">​</a></h2><ul><li>[ ] SIGTERM drains in-flight turns (bounded), closes MCP children, flushes logs and telemetry.</li><li>[ ] MCP children reconnect on a transport failure (built in); <code>/api/health</code> shows reconnect counts.</li><li>[ ] Sessions hydrate lazily and evict (<code>AGENT_SESSION_CACHE</code>); nothing loads everything at boot.</li><li>[ ] History windows on turn boundaries and heals tool pairs (built in).</li><li>[ ] Degradation paths are typed and friendly: model chain exhausted → 503 with the draft saved; counter store down → fail open; STT down → a typed error.</li><li>[ ] <code>/api/health</code> is the deploy&#39;s readiness probe (503 when no key or no tools).</li></ul><h2 id="_5-cost-abuse" tabindex="-1">5. Cost &amp; abuse <a class="header-anchor" href="#_5-cost-abuse" aria-label="Permalink to &quot;5. Cost &amp; abuse&quot;">​</a></h2><ul><li>[ ] Rate limits on session creation, turns per session, turns per IP, uploads, transcriptions; one in-flight turn per session; a global in-flight cap; <code>AGENT_TRUST_PROXY</code> only behind a proxy.</li><li>[ ] Usage caps in plan tokens per user (5h/day/week/month) and per session; context cap; users see a percentage.</li><li>[ ] Tool-output trimming on; the typed prompt on for multi-variant domains; a cheap decision instead of a model call for routing.</li><li>[ ] Model endpoints priced (<code>LLM_&lt;NAME&gt;_PRICE</code>) so the ledger carries vendor cost; metering sink configured if you bill.</li></ul><h2 id="_6-observability" tabindex="-1">6. Observability <a class="header-anchor" href="#_6-observability" aria-label="Permalink to &quot;6. Observability&quot;">​</a></h2><ul><li>[ ] <code>AGENT_O2_URL</code> (or an OTLP collector) set; traces, metrics and logs arrive; the behaviour panel shows runtime interventions.</li><li>[ ] Alerts: turn error ratio, model unavailable, circuit open, rate-limit bursts, p95 latency, cost per hour.</li><li>[ ] <code>npm run check:otel</code> green in CI; the privacy scan finds no user text in labels.</li><li>[ ] Structured logs ship off the main thread; retention set (<code>AGENT_LOG_RETENTION_DAYS</code>, <code>AGENT_SESSION_RETENTION_DAYS</code>).</li></ul><h2 id="_7-deploy-hygiene" tabindex="-1">7. Deploy hygiene <a class="header-anchor" href="#_7-deploy-hygiene" aria-label="Permalink to &quot;7. Deploy hygiene&quot;">​</a></h2><ul><li>[ ] Docker runs as a non-root user with a HEALTHCHECK; images build from the repo root.</li><li>[ ] A compose stack with TLS in front (deploy/) and a tested runbook (deploy/DEPLOY.md).</li><li>[ ] <code>.env.production.example</code> documents EVERY variable and stays current.</li><li>[ ] Multi-node: Redis + Mongo configured; sticky sessions recommended (in-flight guards are per node).</li></ul><h2 id="_8-data-safety-rails-dev-time" tabindex="-1">8. Data safety rails (dev time) <a class="header-anchor" href="#_8-data-safety-rails-dev-time" aria-label="Permalink to &quot;8. Data safety rails (dev time)&quot;">​</a></h2><ul><li>[ ] All writes gated by <code>AGENT_ALLOW_WRITES=true</code>; the eval gateway runs with writes off; the runner refuses write scenarios otherwise.</li><li>[ ] Probe/seed scripts require <code>--yes</code>, tag their records, clean up, report what they could not clean.</li><li>[ ] Secrets only in <code>.env</code> (gitignored); a committed <code>.env.example</code> with placeholders.</li><li>[ ] PII scrubbed from read-tool results (contact fields) before anything reaches the model.</li></ul><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/PRODUCTION-CHECKLIST.md">docs/PRODUCTION-CHECKLIST.md</a> — edit it there; the site mirrors the repository.</small></p>',20)])])}const m=i(r,[["render",s]]);export{p as __pageData,m as default};
